import time, os, statistics, hashlib
from cryptography.hazmat.primitives import hashes
size=20_480_000
pt=os.urandom(size)

def bench(f, runs=5):
    times=[]
    for _ in range(runs):
        t0=time.perf_counter(); f(); times.append(time.perf_counter()-t0)
    return statistics.mean(times)

def crypt():
    digest=hashes.Hash(hashes.SHA256()); digest.update(pt); digest.finalize()

def hl():
    hashlib.sha256(pt).digest()
print('crypto', bench(crypt), 'hashlib', bench(hl))
